import * as React from "react";

export type AmplifierStackIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function AmplifierStackIcon({ size = 20, ...props }: AmplifierStackIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="4" y="4" width="16" height="7" rx="1" /><rect x="4" y="13" width="16" height="7" rx="1" /><circle cx="8" cy="7.5" r="1" /><circle cx="8" cy="16.5" r="1" />
    </svg>
  );
}
